#' Trajectory K-Means
#'
#' 
#' @param data .
#' @param vars Numeric repeated-measure variables representing time points.
#' @param run .
#' @param nclust Number of trajectory clusters.
#' @param standardize Standardizes repeated-measure variables before
#'   clustering.
#' @param missing .
#' @param nstart Number of random starting configurations passed to
#'   stats::kmeans().
#' @param itermax Maximum number of iterations passed to stats::kmeans().
#' @param algorithm K-means algorithm used by stats::kmeans().
#' @param seed Random seed for reproducible clustering.
#' @param showSummary .
#' @param showCenters .
#' @param showFit .
#' @param showPlot .
#' @param showZPlot .
#' @param plotType .
#' @param lineAlpha .
#' @param angle .
#' @param showElbow .
#' @param maxK .
#' @param centerScale Scale used to display cluster centers.
#' @param showSilhouette .
#' @param showSilPlot .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$fit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$silhouette} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$centers} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$member} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot1} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$elbow} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$silplot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
long <- function(
    data,
    vars,
    run = FALSE,
    nclust = 3,
    standardize = TRUE,
    missing = "listwise",
    nstart = 25,
    itermax = 100,
    algorithm = "Hartigan-Wong",
    seed = 1234,
    showSummary = TRUE,
    showCenters = TRUE,
    showFit = TRUE,
    showPlot = TRUE,
    showZPlot = FALSE,
    plotType = "individual",
    lineAlpha = 0.25,
    angle = 0,
    showElbow = FALSE,
    maxK = 8,
    centerScale = "original",
    showSilhouette = TRUE,
    showSilPlot = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("long requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- longOptions$new(
        vars = vars,
        run = run,
        nclust = nclust,
        standardize = standardize,
        missing = missing,
        nstart = nstart,
        itermax = itermax,
        algorithm = algorithm,
        seed = seed,
        showSummary = showSummary,
        showCenters = showCenters,
        showFit = showFit,
        showPlot = showPlot,
        showZPlot = showZPlot,
        plotType = plotType,
        lineAlpha = lineAlpha,
        angle = angle,
        showElbow = showElbow,
        maxK = maxK,
        centerScale = centerScale,
        showSilhouette = showSilhouette,
        showSilPlot = showSilPlot)

    analysis <- longClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

